using DAO.Ortak; using System; using System.Data;
namespace DAO.Repositories.Portal { public class DuyuruGosterimRepository { private readonly DbClass db; private readonly CrudQueryBuilder b; public DuyuruGosterimRepository():this(new DbClass()){} public DuyuruGosterimRepository(DbClass db){if(db==null)throw new ArgumentNullException("db");this.db=db;b=new CrudQueryBuilder();} public DataTable SelectById(int id){var q=new SqlQuery("SELECT * FROM DuyuruGosterim_Table WHERE Id=@Id");q.AddParameter("@Id",id);return db.SelectFromDb(q,"");} public DataTable SelectAll(){return db.SelectFromDb(new SqlQuery("SELECT * FROM DuyuruGosterim_Table"),"");} public DataTable SelectByDuyuruId(int id){var q=new SqlQuery("SELECT * FROM DuyuruGosterim_Table WHERE DuyuruId=@DuyuruId ORDER BY Id DESC");q.AddParameter("@DuyuruId",id);return db.SelectFromDb(q,"");} public int Insert<T>(T x){return db.Insert(b.BuildInsert(x,"DuyuruGosterim_Table"));} public bool Update<T>(T x){return db.Update2Db(b.BuildUpdate(x,"DuyuruGosterim_Table"));} public bool Delete(int id){return db.DeleteFromDb(b.BuildDelete("DuyuruGosterim_Table",id),"");} } }
